({
  Offset offset,
  double sx,
  double sy,
  double rotation,
  double opacity,
  double value
}) sampleWebFinale(
  String name,
  double milliseconds, {
  Offset target = Offset.zero,
}) {
  final stops = webFinaleTracks[name]!;
  var a = stops.first;
  var b = a;
  for (final stop in stops.skip(1)) {
    b = stop;
    if (milliseconds <= stop.$1) break;
    a = stop;
  }
  final c = a.$10;
  final t = b.$1 == a.$1
      ? 0.0
      : Cubic(c.$1, c.$2, c.$3, c.$4)
          .transform(((milliseconds - a.$1) / (b.$1 - a.$1)).clamp(0, 1));
  double mix(double x, double y) => x + (y - x) * t;
  return (
    offset: Offset(
      mix(a.$2 + a.$9 * target.dx, b.$2 + b.$9 * target.dx),
      mix(a.$3 + a.$9 * target.dy, b.$3 + b.$9 * target.dy),
    ),
    sx: mix(a.$4, b.$4),
    sy: mix(a.$5, b.$5),
    rotation: mix(a.$6, b.$6),
    opacity: mix(a.$7, b.$7),
    value: mix(a.$8, b.$8),
  );
}
